custom_css:
/* === 液态太妃糖 (Liquid Toffee) UI 感谢代码楼里老师们的代码https://discord.com/channels/1291925535324110879/1380392618336194702
感谢尾老师，类名，输入框伪提示词来自尾老师，hy老师的去除思维链箭头，na老师的悬浮底栏和思维链文字自定义，楼层信息自定义，12老师的去思维链背景色。感谢NA老师的去阴影，感谢咩野老师的去除全局阴影.=== */

/* --- 1. 字体引入 --- */
@import url('https://fonts.googleapis.com/css2?family=Mali:wght@400;600&family=Quicksand:wght@400;600;700&display=swap');
@import url("https://fontsapi.zeoseven.com/802/main/result.css"); 
@import url("https://fontsapi.zeoseven.com/45/main/result.css");  
@import url("https://fontsapi.zeoseven.com/813/main/result.css");  
@import url("https://fontsapi.zeoseven.com/497/main/result.css"); 

/* --- 2. 核心梦境颜色与样式变量 (太妃果冻系) --- */
:root {
    --theme-bg-color: #FDF8F5; 
    --theme-bg-mid: #F5E6DA; 
    --card-bg: rgba(255, 252, 248, 0.75); 
    --accent-toffee: #C88A58; 
    --accent-caramel: #D49A6A; 
    --accent-cream: #E8C39E;
    --text-main: #5C4033; 
    --text-subtle: #8B6D5A; 

    --font-english-script: 'Mali', cursive;
    --font-english-serif: 'Quicksand', sans-serif;
    --font-main: "YShi-Written", var(--font-english-serif), sans-serif;
    --font-quote: "Yomeng Script", var(--font-english-script), cursive;
    --font-code: "nzgrRuYinZouZhangKai", monospace;
    --font-title: "pingfangzhangyalinheifang", var(--font-english-serif), sans-serif;
}

/* --- 新增：太妃糖反选色与滚动条 --- */
::selection { background-color: rgba(200, 138, 88, 0.4); color: var(--text-main); }
::-webkit-scrollbar { width: 6px; height: 6px; }
::-webkit-scrollbar-track { background: transparent; }
::-webkit-scrollbar-thumb { background: rgba(200, 138, 88, 0.3); border-radius: 10px; }
::-webkit-scrollbar-thumb:hover { background: rgba(200, 138, 88, 0.6); }

/* --- 3. 全局样式：去阴影、去边框 --- */
* { box-shadow: none !important; border-style: none !important; }
body { 
    background-color: var(--theme-bg-color) !important; 
    background-image: linear-gradient(135deg, rgba(253,248,245,0.9) 0%, rgba(245,230,218,0.7) 100%);
    background-size: cover;
    background-position: center top;
    background-attachment: fixed;
    color: var(--text-main); 
    font-family: var(--font-main); 
    font-weight: normal; 
}

/* 新增：焦糖漩涡与漂浮气泡 */
body::after {
    content: ''; position: fixed; top: -50vh; left: -50vw; width: 200vw; height: 200vh;
    background: conic-gradient(from 0deg at 50% 50%, rgba(200,138,88,0.03) 0%, transparent 20%, rgba(212,154,106,0.03) 40%, transparent 60%, rgba(232,195,158,0.03) 80%, transparent 100%);
    pointer-events: none; z-index: 9998; mix-blend-mode: multiply;
    animation: toffee-spin 45s linear infinite;
}
body::before {
    content: ''; position: fixed; top: 0; left: 0; width: 100vw; height: 100vh;
    background-image: radial-gradient(circle at 15% 50%, rgba(212,154,106,0.04) 0%, transparent 8%), radial-gradient(circle at 85% 30%, rgba(200,138,88,0.03) 0%, transparent 6%), radial-gradient(circle at 50% 80%, rgba(232,195,158,0.05) 0%, transparent 10%);
    pointer-events: none; z-index: 9999; 
    animation: caramel-bubbles 15s ease-in-out infinite alternate;
}
@keyframes toffee-spin { 0% { transform: rotate(0deg); } 100% { transform: rotate(360deg); } }
@keyframes caramel-bubbles { 0% { transform: translateY(0) scale(1); opacity: 0.8; } 100% { transform: translateY(-30px) scale(1.1); opacity: 1; } }

/* 特殊标签字体应用 */
code, pre, .mes_text code { font-family: var(--font-code) !important; color: var(--accent-toffee) !important; }
blockquote { 
    font-family: var(--font-quote) !important; 
    color: var(--text-subtle) !important; 
    background: rgba(245, 230, 218, 0.4);
    border-left: 4px solid var(--accent-toffee) !important;
    border-radius: 0 12px 12px 0;
    padding: 10px 15px;
    margin: 10px 0;
}

#sheld, #character_view { background: transparent !important; margin: 0 auto !important; left: 0; right: 0; border: none !important; overflow: visible !important; }
#chat { background: transparent !important; align-items: center !important; padding-bottom: 120px !important; }
h1, h2, h3, h4, .standoutHeader, .inline-drawer-header, .title_restorable { font-family: var(--font-title); color: var(--accent-toffee); font-weight: normal; }

/* --- 4. 顶部导航栏替换 --- */
#top-settings-holder { position:relative; background-color: rgba(253, 248, 245, 0.6); backdrop-filter: blur(12px); border: none !important; }

.drawer-icon.fa-sliders::before, .drawer-icon.fa-plug::before, .drawer-icon.fa-font::before, .drawer-icon.fa-book-atlas::before, .drawer-icon.fa-user::before, .drawer-icon.fa-image::before, .drawer-icon.fa-cubes::before, .drawer-icon.fa-bars-progress::before, .drawer-icon.fa-face-smile::before, .drawer-icon.fa-address-card::before,
#ai-config-button .drawer-icon::before, #advanced-formatting-button .drawer-icon::before, #user-settings-button .drawer-icon::before, #extensions-settings-button .drawer-icon::before, #persona-management-button .drawer-icon::before,
#sys-settings-button .drawer-icon::before, #WI-SP-button .drawer-icon::before, #table_database_settings_drawer .drawer-icon::before, #character_popup_button .drawer-icon::before, #backgrounds-button .drawer-icon::before {
    content: '' !important; font-size: 0 !important;
}

.drawer-icon.fa-sliders, .drawer-icon.fa-plug, .drawer-icon.fa-font, .drawer-icon.fa-book-atlas, .drawer-icon.fa-user, .drawer-icon.fa-image, .drawer-icon.fa-cubes, .drawer-icon.fa-bars-progress, .drawer-icon.fa-face-smile, .drawer-icon.fa-address-card,
#ai-config-button .drawer-icon, #advanced-formatting-button .drawer-icon, #user-settings-button .drawer-icon, #extensions-settings-button .drawer-icon, #persona-management-button .drawer-icon,
#sys-settings-button .drawer-icon, #WI-SP-button .drawer-icon, #table_database_settings_drawer .drawer-icon, #character_popup_button .drawer-icon, #backgrounds-button .drawer-icon {
    width: 35px !important; height: 40px !important; background-size: contain !important; background-repeat: no-repeat !important; background-position: center !important; transition: all 0.5s cubic-bezier(0.4, 0, 0.2, 1); 
}

.drawer-icon.fa-sliders:hover, .drawer-icon.fa-plug:hover, .drawer-icon.fa-font:hover, .drawer-icon.fa-book-atlas:hover, .drawer-icon.fa-user:hover, .drawer-icon.fa-image:hover, .drawer-icon.fa-cubes:hover, .drawer-icon.fa-bars-progress:hover, .drawer-icon.fa-face-smile:hover, .drawer-icon.fa-address-card:hover, #backgrounds-button .drawer-icon:hover { 
    transform: translateY(-3px) scale(1.1) rotate(5deg); 
}

/* 分组1替换 */
.drawer-icon.fa-sliders, .drawer-icon.fa-font, .drawer-icon.fa-user, .drawer-icon.fa-cubes, .drawer-icon.fa-face-smile,
#ai-config-button .drawer-icon, #advanced-formatting-button .drawer-icon, #user-settings-button .drawer-icon, #extensions-settings-button .drawer-icon, #persona-management-button .drawer-icon {
    background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260509/FOZs/1065X1767/2026-05-09%2520133222.png/webp') !important; 
}

/* 分组2替换 */
.drawer-icon.fa-plug, .drawer-icon.fa-book-atlas, .drawer-icon.fa-image, .drawer-icon.fa-bars-progress, .drawer-icon.fa-address-card,
#sys-settings-button .drawer-icon, #WI-SP-button .drawer-icon, #table_database_settings_drawer .drawer-icon, #character_popup_button .drawer-icon, #backgrounds-button .drawer-icon {
    background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260509/IDwB/1501X1424/2026-05-09%2520133236.png/webp') !important; 
}

/* --- 抽屉与弹窗背景图替换 --- */
.drawer-content {
    background-image: linear-gradient(rgba(253, 248, 245, 0.7), rgba(253, 248, 245, 0.85)), url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260509/3POi/1200X675/06402fa7e3610b81f84bea0bc34f2b62.jpg/webp') !important;
    background-size: cover; background-position: center;
    border-radius: 12px !important; color: var(--text-main) !important;
}
dialog.popup .popup-body, #dialogue_popup {
    background-image: linear-gradient(rgba(253, 248, 245, 0.7), rgba(253, 248, 245, 0.85)), url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260509/3POi/1200X675/06402fa7e3610b81f84bea0bc34f2b62.jpg/webp') !important;
    background-size: cover; background-position: center;
    border-radius: 12px !important; color: var(--text-main) !important;
}

/* --- 5. 底部悬浮输入栏 --- */
#form_sheld { position: absolute !important; bottom: 10px !important; left: 0; right: 0; display: flex; justify-content: center; z-index: 1000; pointer-events: none; }
#send_form { width: 90% !important; max-width: 800px !important; pointer-events: auto; }

#send_form, body.no-blur #send_form { 
    border-radius: 25px !important; 
    background-color: rgba(255, 252, 248, 0.7) !important; 
    padding: 10px 15px !important; 
    backdrop-filter: blur(15px) saturate(150%) !important; 
    -webkit-backdrop-filter: blur(15px) saturate(150%) !important; 
    border: none !important; 
    box-shadow: none !important; 
    transition: all 0.5s ease !important; 
}
#send_form:hover, body.no-blur #send_form:hover { transform: translateY(-5px); background-color: rgba(255, 252, 248, 0.9) !important; }

#rightSendForm, #leftSendForm { gap: 10px; }
#send_textarea { clip-path: none !important; border: none !important; background: transparent !important; color: var(--text-main) !important; font-size: 1rem !important; box-shadow: none !important; }

#nonQRFormItems { position: relative; display: flex; align-items: center; justify-content: center; width: 100%; }
#send_textarea::placeholder { color: transparent !important; text-shadow: none !important; }

/* 伪提示词 - 太妃糖主题 */
#nonQRFormItems:has(#send_textarea:placeholder-shown)::before { 
    content: 'Melting sweet toffee... 🍮✨'; 
    color: var(--accent-toffee); 
    position: absolute; 
    top: 50%; left: 50%; 
    transform: translate(-50%, -50%); 
    width: max-content; 
    max-width: 60%; 
    text-align: center; 
    font-family: var(--font-english-script); 
    font-size: clamp(0.9rem, 1.5vw, 1.2rem); 
    pointer-events: none; 
    white-space: nowrap; 
    overflow: hidden; 
    text-overflow: ellipsis;
    opacity: 0.7; 
    animation: toffee-glow 3s infinite alternate;
}
@keyframes toffee-glow { 0% { opacity: 0.5; transform: translate(-50%, -50%) scale(0.98); } 100% { opacity: 1; transform: translate(-50%, -50%) scale(1.02); filter: drop-shadow(0 0 4px rgba(200,138,88,0.4)); } }

/* 底栏图标替换 */
#options_button *, #send_but *, #extensionsMenuButton * { display: none !important; }
#options_button, #send_but, #extensionsMenuButton { 
    display: inline-flex !important;
    width: 38px !important; height: 38px !important; min-width: 38px !important;
    background-size: contain !important; background-repeat: no-repeat !important; background-position: center !important; 
    transition: transform 0.3s cubic-bezier(0.175, 0.885, 0.32, 1.275); font-size: 0 !important; border: none !important; background-color: transparent !important; 
    padding: 0 !important; color: transparent !important;
}
#options_button:hover, #send_but:hover, #extensionsMenuButton:hover { transform: scale(1.2) rotate(8deg); }

#options_button { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260509/tZrm/1301X1395/2026-05-09%2520133209.png/webp') !important; }
#extensionsMenuButton { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260509/JVji/1277X1466/2026-05-09%2520133159.png/webp') !important; }
#send_but { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260509/5OnK/1519X1533/2026-05-09%2520133147.png/webp') !important; }

#ai_retry_button, #auto_completion_button, #mes_impersonate { color: var(--accent-toffee) !important; background-color: transparent !important; transition: transform 0.3s cubic-bezier(0.175, 0.885, 0.32, 1.275); border: none !important; }
#ai_retry_button:hover, #auto_completion_button:hover, #mes_impersonate:hover { transform: scale(1.2) rotate(8deg); }

/* --- 6. 核心：消息框设计 (奶冻双层包裹质感) --- */
.mes { 
    display: flex; flex-direction: column; 
    padding: 0 !important; 
    margin: 100px auto 50px !important; 
    width: 90%; max-width: 800px; 
    background-color: var(--card-bg) !important;
    backdrop-filter: blur(12px) saturate(150%);
    -webkit-backdrop-filter: blur(12px) saturate(150%);
    border-radius: 24px !important;
    position: relative;
    border: 2px solid rgba(255, 255, 255, 0.9) !important;
    /* 奶油果冻层 */
    box-shadow: 0 0 0 10px rgba(255, 252, 248, 0.5) !important;
    overflow: visible !important; 
    contain: none !important;
}

/* 楼层与时间戳 */
.mes .mesIDDisplay, .mes .mes_timer, .mes .mes_timestamp {
    position: absolute !important;
    bottom: -18px !important; 
    top: auto !important; 
    height: 28px !important;
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
    z-index: 40 !important;
    font-family: var(--font-english-serif) !important;
    font-size: 12px !important;
    font-weight: 800 !important;
    white-space: nowrap !important;
    box-shadow: 0 4px 10px rgba(200, 138, 88, 0.15) !important;
    transition: all 0.5s cubic-bezier(0.68, -0.55, 0.265, 1.55) !important; 
}

/* 楼层信息 (焦糖吊坠) */
.mes .mesIDDisplay {
    left: 50% !important;
    transform: translateX(-100%) translateY(0) !important; 
    background: var(--accent-toffee) !important;
    color: #fff !important;
    padding: 0 12px 0 16px !important;
    border-radius: 0 0 0 16px !important; 
    border: 2px solid rgba(255, 252, 248, 0.9) !important;
    border-right: none !important; 
    border-top: none !important; 
}
.mesIDDisplay::before { content: '🍮 No.' !important; color: #fff !important; margin-right: 3px; font-weight: normal;}
.mesIDDisplay::after { content: '' !important; }

/* 时间戳 (奶油吊坠) */
.mes .mes_timer, .mes .mes_timestamp {
    left: 50% !important;
    transform: translateX(0) translateY(0) !important; 
    background: rgba(253, 248, 245, 0.95) !important;
    color: var(--accent-toffee) !important;
    padding: 0 16px 0 12px !important;
    border-radius: 0 0 16px 0 !important; 
    border: 2px solid rgba(255, 252, 248, 0.9) !important;
    border-left: 1px dashed rgba(200, 138, 88, 0.4) !important; 
    border-top: none !important;
    backdrop-filter: blur(4px) !important;
}
.mes .mes_timer::before, .mes .mes_timestamp::before { content: '☕ ' !important; font-weight: normal; margin-right: 3px;}

.mes:hover .mesIDDisplay { transform: translateX(calc(-100% - 4px)) translateY(6px) !important; border-radius: 16px !important; border: 2px solid rgba(255, 252, 248, 0.9) !important; background: var(--accent-caramel) !important; }
.mes:hover .mes_timer, .mes:hover .mes_timestamp { transform: translateX(4px) translateY(6px) !important; border-radius: 16px !important; border: 2px solid rgba(255, 252, 248, 0.9) !important; }

/* 消息框顶部背景横幅 */
.mes .mesAvatarWrapper {
    display: block; padding: 0;
    width: 100%; height: 200px !important; min-height: 200px !important;
    position: relative; z-index: 5; 
    overflow: visible !important; 
    border-radius: 24px 24px 0 0;
    border: none !important;
}
.mes .mesAvatarWrapper::before {
    content: ''; position: absolute; top: 0; left: 0; right: 0; bottom: 0;
    background-size: cover; background-position: center 30%; background-repeat: no-repeat;
    border-radius: 22px 22px 0 0; 
    -webkit-mask-image: linear-gradient(to bottom, rgba(0,0,0,1) 20%, rgba(0,0,0,0) 100%);
    mask-image: linear-gradient(to bottom, rgba(0,0,0,1) 20%, rgba(0,0,0,0) 100%);
    z-index: -1; pointer-events: none;
}
.mes[is_user="false"] .mesAvatarWrapper::before { 
    background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260509/dINv/720X541/e9a4a8f5f3995d3e4d21f990361a00d8.jpg/webp'); 
}
.mes[is_user="true"] .mesAvatarWrapper::before { 
    background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260509/hv93/736X599/d04372f9da837027f13a1f36d53675c3.jpg/webp'); 
}

/* 头像悬浮果冻框 */
.mes .avatar {
    position: absolute; top: -50px; width: 90px; height: 90px; 
    background: rgba(255, 252, 248, 0.8) !important; 
    backdrop-filter: blur(4px) !important;
    padding: 4px !important; z-index: 100 !important; 
    display: flex !important; align-items: center; justify-content: center;
    border-radius: 50% !important; border: none !important;
    box-shadow: 0 0 0 4px rgba(255, 252, 248, 0.6) !important;
    animation: cream-breathe 4s infinite ease-in-out;
}
.mes[is_user="false"] .avatar { left: 20px; }
.mes[is_user="true"] .avatar { right: 20px; left: auto; }
.mes .avatar img { width: 100% !important; height: 100% !important; object-fit: cover !important; border-radius: 50% !important; }
@keyframes cream-breathe {
    0% { transform: translateY(0) scale(1); background: rgba(255, 252, 248, 0.8); } 
    50% { transform: translateY(-5px) scale(1.05); background: rgba(245, 230, 218, 0.95); } 
    100% { transform: translateY(0) scale(1); background: rgba(255, 252, 248, 0.8); }
}

/* 消息主体与水印 */
.mes .mes_block { background-color: transparent !important; background-image: none !important; padding: 20px 40px 50px 40px !important; position: relative; border: none !important; overflow: visible !important; min-height: 120px !important; z-index: 10; }
.mes .mes_text, .mes_reasoning { background: transparent !important; border: none !important; padding: 0 !important; margin: 0 !important; backdrop-filter: none !important; position: relative; z-index: 10 !important; }

.mes_block::after {
    content: 'LIQUID TOFFEE \A 🍯 MELTING SWEET'; white-space: pre;
    position: absolute; top: 30px; color: rgba(200, 138, 88, 0.06);
    font-family: var(--font-english-serif); font-size: 32px; text-align: left; font-weight: 800; letter-spacing: 2px;
    z-index: 0; pointer-events: none; user-select: none;
    animation: float-syrup 7s infinite ease-in-out alternate;
}
@keyframes float-syrup { 0% { transform: translateY(0) scale(1) skew(0deg); } 100% { transform: translateY(-8px) scale(1.02) skew(-2deg); } }
.mes[is_user="false"] .mes_block::after { left: 40px; }
.mes[is_user="true"] .mes_block::after { left: 40px; }

/* --- 8. 思维链自定义 --- */
summary.mes_reasoning_summary, .mes_reasoning_header { background: transparent !important; border: none !important; padding: 0 !important; margin-bottom: 10px !important; }
summary.mes_reasoning_summary *, .mes_reasoning_header h4, .mes_reasoning_header_title { font-size: 0 !important; visibility: hidden; display: none !important; }
summary.mes_reasoning_summary::before, .mes_reasoning_header::before { 
    content: "🤎 Boiling caramel thoughts... 🍮✨"; 
    font-family: var(--font-english-script); 
    font-size: 16px !important; 
    color: var(--accent-toffee); visibility: visible; letter-spacing: 1px; font-weight: bold;
    display: block !important;
}
.mes_reasoning { padding-left: 20px !important; margin-bottom: 30px !important; color: var(--text-subtle); font-family: var(--font-quote); font-size: 1.05em; position: relative; }
.mes_reasoning::before { 
    content: ''; position: absolute; left: 0; top: 5px; bottom: 5px; width: 4px; 
    background: linear-gradient(to bottom, transparent, var(--accent-toffee), transparent);
    border-radius: 4px;
}
.mes .mes_text { line-height: 2.3; color: var(--text-main); font-size: 16px; text-align: justify; letter-spacing: 0.5px; }

/* 消息按钮组 */
.mes .mes_buttons, .mes .mes_edit_buttons { flex-direction: row-reverse; gap: 10px; opacity: 0; transition: opacity 0.4s ease; pointer-events: auto !important; margin-top: 15px; position: relative; z-index: 15; align-items: center; }
.mes:hover .mes_buttons, .mes:hover .mes_edit_buttons { opacity: 1; }
.mes .mes_buttons .mes_button, .mes .mes_edit_buttons .mes_button { background-color: rgba(253, 248, 245, 0.8) !important; color: var(--accent-toffee) !important; padding: 6px !important; border-radius: 50% !important; cursor: pointer; transition: all 0.3s cubic-bezier(0.25, 0.8, 0.25, 1); font-size: 14px !important; border: none !important; }
.mes .mes_buttons .mes_button:hover, .mes .mes_edit_buttons .mes_button:hover { background-color: var(--accent-toffee) !important; color: #fff !important; transform: scale(1.15) rotate(10deg); }

/* 打字指示器适配果冻态 */
#typing_indicator { background-color: transparent !important; border: none !important; margin: 15px auto !important; }
#typing_indicator .dot { background-color: var(--accent-toffee) !important; animation: jelly-bounce 1.5s infinite ease-in-out both; }
@keyframes jelly-bounce { 0%, 80%, 100% { transform: scale(0); opacity: 0.3; } 40% { transform: scale(1); opacity: 1; } }

/* --- 9 & 10. 全局UI设定 --- */
.standoutHeader, .inline-drawer-header, .title_restorable, #extensions_settings2 > div, #extensions_settings > div, .openai_logit_bias_preset_form, details > summary, #power-user-options-block h4, #InstructSettingsColumn h4, #SystemPromptColumn h4, #ContextSettings h4, .persona_management_global_settings h4, #character_popup h4, #AdvancedFormatting h4, #rm_group_chats_block h4, div[name*='HandlingToggles'] h4, div[name*='MiscellaneousToggles'] h4 { background: rgba(253, 248, 245, 0.6) !important; backdrop-filter: blur(8px); border-radius: 12px !important; padding: 12px 18px !important; margin-bottom: 10px !important; color: var(--text-main) !important; border: none !important; }
input[type="text"], input[type="number"], input[type="search"], textarea, select, .text_pole { background-color: rgba(245, 230, 218, 0.4) !important; color: var(--text-main) !important; border-radius: 12px !important; padding: 10px !important; border: none !important; font-family: var(--font-english-serif); }
input:focus, textarea:focus, select:focus { outline: none !important; background-color: rgba(255, 252, 248, 0.95) !important; border: none !important; }
.menu_button { background-color: rgba(253, 248, 245, 0.8) !important; color: var(--text-main) !important; transition: all 0.4s ease; border-radius: 10px !important; font-weight: 800; border: none !important; }
.menu_button:hover { background-color: var(--accent-toffee) !important; color: white !important; transform: translateY(-2px); }
input[type="checkbox"]:checked::before { box-shadow: inset 1em 1em var(--accent-toffee) !important; }

dialog.popup { background-color: transparent !important; }
dialog.popup .popup-body::before, #dialogue_popup::before { content: ''; position: absolute; top: 0; left: 0; right: 0; bottom: 0; background-color: rgba(253, 248, 245, 0.88); z-index: 0; border-radius: 12px; }
dialog.popup .popup-body > *, #dialogue_popup > * { position: relative; z-index: 1; }
.menu_button.active, .menu_button.world_set, .menu_button.fav_on, #left-nav-panel .menu_button.selected { background-color: var(--accent-toffee) !important; color: #fff !important; letter-spacing: 1px; border: none !important; }

/* 手机端自适应 */
@media (max-width: 768px) {
    .mes { margin: 80px auto 40px !important; width: 95% !important; }
    .mes > .ch_name, .mes .mes_block > .ch_name { top: -55px !important; padding: 4px 12px !important; }
    .mes .ch_name .name_text { font-size: 15px !important; }
    .mes .mesIDDisplay, .mes .mes_timer, .mes .mes_timestamp { bottom: -15px !important; height: 24px !important; font-size: 10px !important; }
    .mes .avatar { width: 70px; height: 70px; top: -35px; }
    .mes .mesAvatarWrapper { height: 140px !important; min-height: 140px !important; }
    .mes_block::after { font-size: 20px; left: 20px !important; }
}

#dialogue_popup { z-index: 10000 !important; pointer-events: auto !important; }
#dialogue_del_mes_ok, #dialogue_del_mes_cancel { background-color: rgba(253, 248, 245, 0.9) !important; color: var(--text-main) !important; border-radius: 10px !important; padding: 12px 24px !important; margin: 10px 8px !important; transition: all 0.4s ease !important; border: none !important; font-weight: 800; }
#dialogue_del_mes_ok:hover { background-color: var(--accent-toffee) !important; color: #fff !important; transform: translateY(-3px) !important; }
#dialogue_del_mes_cancel:hover { background-color: var(--accent-cream) !important; color: var(--text-main) !important; transform: translateY(-3px) !important; }

/* =========================================
   ✨ 正文文字美化与装饰 (太妃糖浆动效)
   ========================================= */
.mes .mes_text p {
    color: var(--text-main) !important;
    line-height: 1.85 !important;
    letter-spacing: 0.8px !important;
    margin-bottom: 1.2em !important;
    text-shadow: 0px 1px 1px rgba(255, 255, 255, 0.9) !important;
    transition: all 0.3s cubic-bezier(0.25, 0.8, 0.25, 1) !important;
    position: relative;
}
.mes .mes_text p:hover {
    color: #3D2B1F !important; 
    text-shadow: 0px 1px 2px rgba(232, 195, 158, 0.6) !important;
    transform: translateX(2px);
}

/* 强调文字：焦糖糖浆划线 */
.mes .mes_text p strong {
    color: #A0522D !important; 
    font-weight: 800 !important;
    background-image: linear-gradient(transparent 60%, rgba(200, 138, 88, 0.25) 60%, rgba(200, 138, 88, 0.25) 100%);
    background-repeat: no-repeat;
    background-size: 100% 100%;
    padding: 0 4px;
    border-radius: 4px;
    border-bottom: 2px solid rgba(212, 154, 106, 0.8);
    transition: all 0.3s ease;
}
.mes .mes_text p strong:hover { background-image: linear-gradient(transparent 20%, rgba(200, 138, 88, 0.4) 20%, rgba(200, 138, 88, 0.4) 100%); }

/* 动作/心理描写：拿铁咖啡飘浮色 */
.mes .mes_text p em {
    font-family: var(--font-english-script), var(--font-quote) !important;
    font-style: italic !important;
    background: linear-gradient(45deg, #C88A58, #E8C39E);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    text-shadow: none !important;
    font-weight: 600;
    padding: 0 4px;
    display: inline-block;
    animation: coffee-steam 3s infinite ease-in-out alternate;
}
@keyframes coffee-steam { 0% { transform: translateY(0px) skewX(0deg); } 100% { transform: translateY(-1px) skewX(-2deg); } }

/* =========================================
   悬浮丝带标签 (焦糖牛奶独立贴标)
   ========================================= */
.mes > .ch_name, .mes .mes_block > .ch_name { 
    display: flex !important; position: absolute; 
    top: -70px !important; 
    width: max-content !important; 
    background: rgba(255, 252, 248, 0.95) !important; 
    backdrop-filter: blur(12px) !important;
    border: none !important; 
    padding: 8px 20px !important; 
    z-index: 40 !important;
    align-items: center !important;
    gap: 12px !important;
    box-shadow: 0 4px 15px rgba(200, 138, 88, 0.2) !important;
    transition: all 0.4s cubic-bezier(0.25, 0.8, 0.25, 1) !important;
}

.mes[is_user="false"] > .ch_name, .mes[is_user="false"] .mes_block > .ch_name { 
    left: -15px !important; right: auto !important; 
    border-radius: 0 20px 20px 0 !important; 
    border-left: 6px solid var(--accent-toffee) !important;
    transform: rotate(-3deg);
}
.mes[is_user="false"]:hover > .ch_name, .mes[is_user="false"]:hover .mes_block > .ch_name {
    transform: rotate(0deg) translateX(5px);
    background: #FDF8F5 !important;
}

.mes[is_user="true"] > .ch_name, .mes[is_user="true"] .mes_block > .ch_name { 
    right: -15px !important; left: auto !important; 
    border-radius: 20px 0 0 20px !important;
    border-right: 6px solid var(--accent-caramel) !important;
    transform: rotate(3deg);
}
.mes[is_user="true"]:hover > .ch_name, .mes[is_user="true"]:hover .mes_block > .ch_name {
    transform: rotate(0deg) translateX(-5px);
    background: #FDF8F5 !important;
}

.mes .ch_name > .flex-container { display: flex !important; align-items: center !important; gap: 10px !important; }
.mes .ch_name .name_text { font-family: var(--font-english-serif); font-size: 16px !important; letter-spacing: 1px; color: var(--text-main) !important; font-weight: 800; text-shadow: none !important; }

/* =========================================
   Token计数器果冻标签 (太妃糖主题)
   ========================================= */
div.tokenCounterDisplay {
    background: rgba(255, 252, 248, 0.85) !important;
    backdrop-filter: blur(4px) !important;
    color: var(--accent-toffee) !important;
    border: 2px solid rgba(255, 252, 248, 0.9) !important;
    border-radius: 20px !important; 
    padding: 2px 12px !important;
    font-family: var(--font-english-serif) !important;
    font-size: 11px !important;
    font-weight: 800 !important;
    box-shadow: 0 2px 8px rgba(200, 138, 88, 0.15) !important;
    display: inline-flex !important;
    align-items: center !important;
    justify-content: center !important;
    margin-top: 8px !important;
    transition: all 0.3s cubic-bezier(0.25, 0.8, 0.25, 1) !important;
}

div.tokenCounterDisplay:hover {
    transform: translateY(-2px) scale(1.05) !important;
    background: #FDF8F5 !important; 
    box-shadow: 0 4px 12px rgba(200, 138, 88, 0.25) !important;
}
